UPDATE monitor_sys_gen_server_component_layout SET monitor_sys_gen_server_component_layout_x = CASE monitor_sys_gen_server_component_layout_id
WHEN #{layout.monitorSysGenServerComponentLayoutId} THEN #{layout.monitorSysGenServerComponentLayoutX}
ELSE monitor_sys_gen_server_component_layout_x END, monitor_sys_gen_server_component_layout_y = CASE monitor_sys_gen_server_component_layout_id
WHEN #{layout.monitorSysGenServerComponentLayoutId} THEN #{layout.monitorSysGenServerComponentLayoutY}
ELSE monitor_sys_gen_server_component_layout_y END, monitor_sys_gen_server_component_layout_w = CASE monitor_sys_gen_server_component_layout_id
WHEN #{layout.monitorSysGenServerComponentLayoutId} THEN #{layout.monitorSysGenServerComponentLayoutW}
ELSE monitor_sys_gen_server_component_layout_w END, monitor_sys_gen_server_component_layout_h = CASE monitor_sys_gen_server_component_layout_id
WHEN #{layout.monitorSysGenServerComponentLayoutId} THEN #{layout.monitorSysGenServerComponentLayoutH}
ELSE monitor_sys_gen_server_component_layout_h END, monitor_sys_gen_server_component_layout_z_index = CASE monitor_sys_gen_server_component_layout_id
WHEN #{layout.monitorSysGenServerComponentLayoutId} THEN #{layout.monitorSysGenServerComponentLayoutZIndex}
ELSE monitor_sys_gen_server_component_layout_z_index END, update_time = NOW() WHERE monitor_sys_gen_server_component_layout_id IN
#{layout.monitorSysGenServerComponentLayoutId}
